import{z as n,x as o,o as l,c as p,q as r,j as B,D as E,d as t,s,S as i,b as a}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"涌现能力争论","description":"","frontmatter":{"title":"涌现能力争论","date":"2026-09-08T00:00:00.000Z","section":"llm"},"headers":[],"relativePath":"llm/emergence-debate.md","filePath":"llm/emergence-debate.md","lastUpdated":1791413859000}'),d={name:"llm/emergence-debate.md"};function m(f,e,c,h,D,g){const A=o("Mermaid");return l(),p("div",null,[e[2]||(e[2]=r('<h1 id="涌现能力争论" tabindex="-1">涌现能力争论 <a class="header-anchor" href="#涌现能力争论" aria-label="Permalink to &quot;涌现能力争论&quot;">​</a></h1><div class="epigraph"><p>有些下游指标在某一尺度上近乎从零跳到可用；换成分数式度量之后，同一能力往往早已随损失光滑上升，所谓涌现可以是指标的非线性，而不是损失面的相变。</p><footer>—— Wei et al., Emergent Abilities of Large Language Models, TMLR 2022；Schaeffer, Miranda &amp; Koyejo, Are Emergent Abilities of Large Language Models a Mirage?, NeurIPS 2023</footer></div><p><a href="/llm/scaling-law-fitting">上一课</a>禁止用下游准确率去拟合幂律。缺口正是 Wei 等人称作 <strong>emergent abilities</strong> 的现象：某些任务在小模型上近随机，到某一 \\(N\\) 或 \\(C\\) 突然变好。Schaeffer 等人争辩：若指标是阶跃的（完全匹配、多选对错），光滑的对数似然改善会被折成悬崖；换用连续度量，悬崖消失。本课站在缩放实践里：规划预算时，不要把「涌现点」当成和 Chinchilla 谷底同级的可拟合对象。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Wei 等人收集了若干任务，在对数尺度的参数轴上呈现非线性跳变，并讨论是否需要新的理论。这对产品叙事很强：「不到某规模就没有某能力」。对拟合很危险：你会去找那个拐点并外推它，而拐点依赖题数、提示、以及是否允许部分分。</p><p><span class="marginnote">数字实例：一个只有 5 道题的子集，准确率只能取 0%、20%、40%……100% 这几档。小模型全错停在 0%，稍大一点碰对一题就跳到 20%——「悬崖」有一半只是题数太少带来的台阶，换 500 道题复画就平缓得多。</span></p><p>Schaeffer 等人把同一模型输出改成连续分数（如 token 级概率、编辑距离、Brier），许多悬崖变成平滑曲线。结论不是「没有质变」，而是：<strong>先排除指标非线性，再谈相变</strong>。真正的回路形成（induction 在小模型上也可突然出现）是训练动态，与「70B 才涌现」不是同一命题。</p><p><span class="marginnote">多选题准确率在模型把正确选项 logit 从第 4 抬到第 1 时才动，之前的校准改善全部看不见。这是度量的阈值，不是能力在那一步才被创造。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>报告能力随尺度变化时：</p><ol><li>同时打损失 / BPB 与下游。损失应光滑（拟合课已洗过）；下游若悬崖，先换连续度量复画。</li><li>固定提示与解码（贪婪 vs 采样），多种子。悬崖若随提示移动，那是提示敏感不是尺度相变。</li><li>不要对准确率做对数横轴上的分段回归来「预测涌现点」并据此买卡。</li><li>把训练动态里的突变（阶段课、Olsson）与评测规模曲线分开：前者是某次训练的 step 轴，后者是模型家族的 \\(N\\) 轴。</li></ol><p>若连续度量也出现急剧弯曲，再讨论数据覆盖、回路、或任务是否需要某深度——那是深度对宽度课的表示墙，仍不是准确率拟合出的魔法规模。</p><p><span class="marginnote">直觉类比：连续度量像温度计，每一度都显示；阈值准确率像只报「开/关」的温控器。水温从 30 度一路升到 99 度它都显示「关」，一过 100 度跳「开」——你以为是加热瞬间完成的，其实热量一直在光滑地累积。</span></p>',13)),(l(),B(i,null,{default:E(()=>[s(A,{id:"mermaid-56",class:"mermaid",graph:"flowchart%20TD%0A%20%20C%5B%22%E4%B8%8B%E6%B8%B8%E5%87%86%E7%A1%AE%E7%8E%87%E5%87%BA%E7%8E%B0%E6%82%AC%E5%B4%96%22%5D%20--%3E%20M%5B%22%E5%85%88%E6%8D%A2%E8%BF%9E%E7%BB%AD%E5%BA%A6%E9%87%8F%E5%A4%8D%E7%94%BB%22%5D%0A%20%20M%20--%3E%20S1%7B%22%E6%9B%B2%E7%BA%BF%E5%8F%98%E5%85%89%E6%BB%91%E4%BA%86%3F%22%7D%0A%20%20S1%20--%20%22%E6%98%AF%22%20--%3E%20MIR%5B%22%E5%A4%9A%E5%8D%8A%E6%98%AF%E6%8C%87%E6%A0%87%E9%9D%9E%E7%BA%BF%E6%80%A7%20(%E6%B5%B7%E5%B8%82%E8%9C%83%E6%A5%BC)%22%5D%0A%20%20S1%20--%20%22%E5%90%A6%22%20--%3E%20P%5B%22%E6%8D%A2%E6%8F%90%E7%A4%BA%E4%B8%8E%E8%A7%A3%E7%A0%81%2C%20%E8%B7%91%E5%A4%9A%E7%A7%8D%E5%AD%90%22%5D%0A%20%20P%20--%3E%20S2%7B%22%E6%82%AC%E5%B4%96%E9%9A%8F%E6%8F%90%E7%A4%BA%E7%A7%BB%E5%8A%A8%3F%22%7D%0A%20%20S2%20--%20%22%E7%A7%BB%E5%8A%A8%22%20--%3E%20PS%5B%22%E6%8F%90%E7%A4%BA%E6%95%8F%E6%84%9F%2C%20%E4%B8%8D%E6%98%AF%E5%B0%BA%E5%BA%A6%E7%9B%B8%E5%8F%98%22%5D%0A%20%20S2%20--%20%22%E4%B8%8D%E5%8A%A8%22%20--%3E%20REAL%5B%22%E5%80%99%E9%80%89%E7%9C%9F%E5%BC%AF%E6%9B%B2%3A%20%E6%9F%A5%E6%95%B0%E6%8D%AE%E8%A6%86%E7%9B%96%E4%B8%8E%E6%B7%B1%E5%BA%A6%E5%A2%99%22%5D%0A"})]),fallback:E(()=>[...e[0]||(e[0]=[t(" Loading... ",-1)])]),_:1})),e[3]||(e[3]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>设潜在能力 \\(s\\) 随 \\(N\\) 缓增，指标 \\(1[s\\gt t]\\)。在 \\(s\\) 过 \\(t\\) 时准确率跳变。\\(t\\) 由评分规则决定。改变 \\(t\\)（部分分、pass@k）会移动悬崖位置，这是 Schaeffer 的核心机制解释。它解释了大量「涌现」图，但不声称所有非线性都是假的：softmax 饱和、离散程序突然可执行，也可以产生真弯曲。实践态度是怀疑指标，保留对真弯曲的检验，而不是先验取消质变语言。</p><p><span class="marginnote">术语翻译：pass@k 是「采样 \\(k\\) 次里至少对一次」的概率。\\(k\\) 越大，同一个模型越早「通过」——阈值被 \\(k\\) 自己挪动了。所以「pass@64 上的涌现点比 pass@1 早」不代表能力提前出现，只代表及格线放低了。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不评判哪一篇「赢了」。规划上：计算最优与推理最优用损失与 FLOPs；产品能力用多种度量与提示鲁棒性，不用单一涌现点。把「某规模才突然会某题」写进里程碑，会迫使你买训练最优的大 \\(N\\)，即使连续度量显示小模型过度训练已经够用。</p><p>下一课把「训练计算最优」改成计入<strong>推理</strong>次数的最优——那会把谷底推向更小、训更久的模型，与涌现叙事里「必须更大」进一步分开。</p>',6)),(l(),B(i,null,{default:E(()=>[s(A,{id:"mermaid-75",class:"mermaid",graph:"flowchart%20TD%0A%20%20S%5B%22%E6%BD%9C%E5%9C%A8%E5%88%86%E6%95%B0%E9%9A%8F%E5%B0%BA%E5%BA%A6%E7%BC%93%E5%A2%9E%22%5D%20--%3E%20TH%5B%22%E9%98%88%E5%80%BC%E6%8C%87%E6%A0%87%EF%BC%9A%E5%87%86%E7%A1%AE%E7%8E%87%22%5D%0A%20%20S%20--%3E%20CT%5B%22%E8%BF%9E%E7%BB%AD%E6%8C%87%E6%A0%87%EF%BC%9A%E6%A6%82%E7%8E%87%20%2F%20%E7%BC%96%E8%BE%91%E8%B7%9D%E7%A6%BB%22%5D%0A%20%20TH%20--%3E%20CL%5B%22%E8%A1%A8%E9%9D%A2%E4%B8%8A%E7%9A%84%E6%82%AC%E5%B4%96%22%5D%0A%20%20CT%20--%3E%20SM%5B%22%E5%85%89%E6%BB%91%E6%9B%B2%E7%BA%BF%22%5D%0A"})]),fallback:E(()=>[...e[1]||(e[1]=[t(" Loading... ",-1)])]),_:1})),e[4]||(e[4]=a("h2",{id:"小结",tabindex:"-1"},[t("小结 "),a("a",{class:"header-anchor",href:"#小结","aria-label":'Permalink to "小结"'},"​")],-1)),e[5]||(e[5]=a("ul",null,[a("li",null,"Wei 等人记录了下游指标的尺度非线性；Schaeffer 等人指出阈值度量可把光滑改善折成悬崖。"),a("li",null,"先复画连续度量与提示鲁棒，再谈相变；禁止用准确率拟合涌现点来定 \\(N\\)。"),a("li",null,"训练动态突变与家族尺度曲线是两根轴。"),a("li",null,"规划仍以损失与 FLOPs 为主，能力用多度量。"),a("li",null,"把准确率悬崖写进买卡里程碑，会与过度训练的较小模型抢预算。"),a("li",null,"出处：Wei et al., TMLR 2022；Schaeffer, Miranda & Koyejo, NeurIPS 2023。")],-1))])}const F=n(d,[["render",m]]);export{C as __pageData,F as default};
